using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker();
    }

    // ───────────────────────────────────────────────
    // GetStockLevel Tests
    // ───────────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        var level = _tracker.GetStockLevel("UNKNOWN-SKU");

        Assert.AreEqual(0, level);
    }

    [TestMethod]
    public void GetStockLevel_AfterAddStock_ReturnsAddedQuantity()
    {
        _tracker.AddStock("SKU-001", 25);

        var level = _tracker.GetStockLevel("SKU-001");

        Assert.AreEqual(25, level);
    }

    [TestMethod]
    public void GetStockLevel_AfterMultipleAdds_ReturnsCumulativeQuantity()
    {
        _tracker.AddStock("SKU-002", 10);
        _tracker.AddStock("SKU-002", 5);

        var level = _tracker.GetStockLevel("SKU-002");

        Assert.AreEqual(15, level);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void GetStockLevel_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.GetStockLevel(sku!));
    }

    // ───────────────────────────────────────────────
    // AddStock Tests
    // ───────────────────────────────────────────────

    [TestMethod]
    public void AddStock_ValidSkuAndQuantity_IncreasesStockLevel()
    {
        _tracker.AddStock("SKU-100", 50);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-100"));
    }

    [TestMethod]
    public void AddStock_CalledMultipleTimes_AccumulatesStock()
    {
        _tracker.AddStock("SKU-200", 20);
        _tracker.AddStock("SKU-200", 30);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-200"));
    }

    [TestMethod]
    [DataRow(1)]
    [DataRow(100)]
    [DataRow(999999)]
    public void AddStock_VariousQuantities_AllAccepted(int quantity)
    {
        _tracker.AddStock("SKU-VAR", quantity);

        Assert.AreEqual(quantity, _tracker.GetStockLevel("SKU-VAR"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void AddStock_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.AddStock(sku!, 10));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100)]
    public void AddStock_ZeroOrNegativeQuantity_ThrowsArgumentOutOfRangeException(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _tracker.AddStock("SKU-NEG", quantity));
    }

    [TestMethod]
    public void AddStock_DoesNotAffectOtherSkus()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-B", 20);

        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-B"));
    }

    // ───────────────────────────────────────────────
    // NeedsReorder Tests
    // ───────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsFalse()
    {
        var result = _tracker.NeedsReorder("NONEXISTENT");

        Assert.IsFalse(result);
    }

    [TestMethod]
    [DataRow(1)]
    [DataRow(5)]
    [DataRow(9)]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue(int quantity)
    {
        _tracker.AddStock("LOW-STOCK", quantity);

        var result = _tracker.NeedsReorder("LOW-STOCK");

        Assert.IsTrue(result);
    }

    [TestMethod]
    [DataRow(10)]
    [DataRow(11)]
    [DataRow(100)]
    public void NeedsReorder_StockAtOrAboveThreshold_ReturnsFalse(int quantity)
    {
        _tracker.AddStock("HIGH-STOCK", quantity);

        var result = _tracker.NeedsReorder("HIGH-STOCK");

        Assert.IsFalse(result);
    }

    [TestMethod]
    public void NeedsReorder_StockExactlyAtThreshold_ReturnsFalse()
    {
        _tracker.AddStock("EXACT-10", 10);

        var result = _tracker.NeedsReorder("EXACT-10");

        Assert.IsFalse(result);
    }

    [TestMethod]
    public void NeedsReorder_StockOneBelow_Threshold_ReturnsTrue()
    {
        _tracker.AddStock("JUST-UNDER", 9);

        var result = _tracker.NeedsReorder("JUST-UNDER");

        Assert.IsTrue(result);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void NeedsReorder_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.NeedsReorder(sku!));
    }

    // ───────────────────────────────────────────────
    // Warehouse Transfer / Stock Management Scenarios
    // ───────────────────────────────────────────────

    [TestMethod]
    public void AddStock_MultipleSkus_EachTrackedIndependently()
    {
        _tracker.AddStock("WIDGET", 5);
        _tracker.AddStock("GADGET", 15);
        _tracker.AddStock("WIDGET", 3);

        Assert.AreEqual(8, _tracker.GetStockLevel("WIDGET"));
        Assert.AreEqual(15, _tracker.GetStockLevel("GADGET"));
        Assert.AreEqual(0, _tracker.GetStockLevel("SPROCKET"));
    }

    [TestMethod]
    public void NeedsReorder_AfterRestocking_ReturnsFalse()
    {
        _tracker.AddStock("RESTOCK-SKU", 3);
        Assert.IsTrue(_tracker.NeedsReorder("RESTOCK-SKU"));

        _tracker.AddStock("RESTOCK-SKU", 10);
        Assert.IsFalse(_tracker.NeedsReorder("RESTOCK-SKU"));
    }

    [TestMethod]
    public void FullScenario_TrackMultipleItemsAndCheckReorderStatus()
    {
        _tracker.AddStock("ITEM-A", 5);
        _tracker.AddStock("ITEM-B", 20);
        _tracker.AddStock("ITEM-C", 10);

        Assert.IsTrue(_tracker.NeedsReorder("ITEM-A"), "ITEM-A with 5 units should need reorder");
        Assert.IsFalse(_tracker.NeedsReorder("ITEM-B"), "ITEM-B with 20 units should not need reorder");
        Assert.IsFalse(_tracker.NeedsReorder("ITEM-C"), "ITEM-C with exactly 10 units should not need reorder");

        Assert.AreEqual(5, _tracker.GetStockLevel("ITEM-A"));
        Assert.AreEqual(20, _tracker.GetStockLevel("ITEM-B"));
        Assert.AreEqual(10, _tracker.GetStockLevel("ITEM-C"));
    }
}

